import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] inputs = read(scanner);
        int h = inputs[0];
        int n = inputs[1];
        n -= 1;
        String binaryStr = Integer.toBinaryString(n);
        binaryStr = "0".repeat(Math.max(0, h - binaryStr.length())) + binaryStr;

        StringBuilder s = new StringBuilder();
        for (int i = 0; i < h; i++) {
            if (i > 0 && s.charAt(i - 1) == '0') {
                s.append(binaryStr.charAt(i) == '0' ? '1' : '0');
            } else {
                s.append(binaryStr.charAt(i));
            }
        }

        int ct = 0;
        for (int i = 0; i < h; i++) {
            ct += 1;
            if (s.charAt(i) == '1') {
                ct += Math.pow(2, h - i) - 1;
            }
        }
        System.out.println(ct);
        scanner.close();
    }

    public static int[] read(Scanner scanner) {
        String inputsLine = scanner.nextLine().trim();
        String[] parts = inputsLine.split("\\s+");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }
}

